// Session 4 self-check for Part A (semantic HTML). Do not edit this file.
// It runs every time the page loads and prints a checklist in the Console
// (F12 -> Console). Type selfCheck() in the Console to run it again.
// It only reads the page; it changes nothing.
(function () {
  const HEADINGS = ['H1', 'H2', 'H3', 'H4', 'H5', 'H6'];

  // The cards in the page, plus the card inside <template id="card-template">,
  // so that products added by "Load more" are checked too.
  function allCards() {
    const cards = [...document.querySelectorAll('.card')];
    const tpl = document.querySelector('#card-template');
    if (tpl && tpl.content) cards.push(...tpl.content.querySelectorAll('.card'));
    return cards;
  }

  const checks = [
    {
      name: 'Landmarks: one <main>, plus a <header>, a <nav> and a <footer>',
      test: () =>
        document.querySelectorAll('main').length === 1 &&
        document.querySelector('header') !== null &&
        document.querySelector('nav') !== null &&
        document.querySelector('footer') !== null,
      hint: 'Which box is the top bar, which is the menu, which is the main content, which is the bottom line?',
    },
    {
      name: 'Exactly one <h1>',
      test: () => document.querySelectorAll('h1').length === 1,
      hint: 'The page title is the one <h1>. Product names are the next level down.',
    },
    {
      name: 'Headings never skip a level (h1 -> h2 -> h3, no h1 -> h3)',
      test: () => {
        const levels = [...document.querySelectorAll('h1,h2,h3,h4,h5,h6')]
          .map((h) => Number(h.tagName[1]));
        if (levels.length === 0 || levels[0] !== 1) return false;
        return levels.every((lvl, i) => i === 0 || lvl <= levels[i - 1] + 1);
      },
      hint: 'Pick heading levels by place in the outline, not by font size. style.css sets the size.',
    },
    {
      name: 'Every product name is a heading (also inside the <template>)',
      test: () => {
        const cards = allCards();
        return cards.length > 0 && cards.every((c) => {
          const n = c.querySelector('.name');
          return n !== null && HEADINGS.includes(n.tagName);
        });
      },
      hint: 'A screen-reader user jumps from heading to heading. Each product name should be one.',
    },
    {
      name: 'The catalogue is a list: #catalogue is <ul>, every .card is an <li> (also in the <template>)',
      test: () => {
        const list = document.querySelector('#catalogue');
        return list !== null && (list.tagName === 'UL' || list.tagName === 'OL') &&
          allCards().every((c) => c.tagName === 'LI');
      },
      hint: 'Eight products of the same kind, one after another: that is a list.',
    },
    {
      name: 'Every input has a <label> connected to it',
      test: () => {
        const fields = [...document.querySelectorAll('input, select, textarea')]
          .filter((f) => !['hidden', 'submit', 'button', 'reset'].includes(f.type));
        return fields.length > 0 && fields.every((f) => f.labels && f.labels.length > 0);
      },
      hint: '<label for="q"> with the same id as the input, or the input inside the <label>. Click the label: the cursor should jump into the box.',
    },
    {
      name: 'The search box is inside a <form>',
      test: () => {
        const q = document.querySelector('#q');
        return q !== null && q.form !== null;
      },
      hint: 'A form gives you Enter-to-submit for free. Part B3 needs it.',
    },
    {
      name: 'Every .button and .add is a real <button> (also in the <template>), and no onclick="" attributes',
      test: () => {
        const clickables = [...document.querySelectorAll('.button, .add')];
        const tpl = document.querySelector('#card-template');
        if (tpl && tpl.content) clickables.push(...tpl.content.querySelectorAll('.button, .add'));
        return clickables.length > 0 &&
          clickables.every((b) => b.tagName === 'BUTTON') &&
          document.querySelector('[onclick]') === null;
      },
      hint: 'A <div> cannot be reached with Tab or pressed with Enter. A sold-out button uses the disabled attribute.',
    },
  ];

  function selfCheck() {
    const results = checks.map((c, i) => {
      let ok = false;
      try { ok = Boolean(c.test()); } catch (e) { ok = false; }
      return { n: i + 1, name: c.name, ok, hint: c.hint };
    });
    const passed = results.filter((r) => r.ok).length;
    console.log(`%cSession 4 self-check: ${passed}/${results.length} passed`,
      'font-weight:bold;font-size:14px');
    for (const r of results) {
      if (r.ok) console.log(`%cPASS%c ${r.n}. ${r.name}`, 'color:#1a7f37;font-weight:bold', '');
      else console.log(`%cFAIL%c ${r.n}. ${r.name}\n      hint: ${r.hint}`, 'color:#cf222e;font-weight:bold', '');
    }
    window.__selfCheck = { passed, total: results.length, results };
    return `${passed}/${results.length}`;
  }

  window.selfCheck = selfCheck;
  selfCheck();
})();
